//! Userspace side of the BPF programs in this directory (`main.bpf.c`).
//!
//! - this file: which counting hook the kernel supports, and small helpers
//!   shared by the submodules;
//! - [`maps`]: reading and writing the BPF maps;
//! - [`tc`]: attaching the DSCP marker to interfaces.
//!
//! The skeleton itself (`BpfSkel`) is generated by build.rs into
//! `crate::bpf_skel`, and the C structs shared through `intf.h` are
//! bindgen'd into `crate::bpf_intf`, the same split the sched_ext Rust
//! schedulers use.

pub mod maps;
pub mod tc;

use anyhow::{Context, Result, bail};
use libbpf_rs::btf::{Btf, BtfType};
use log::debug;

use crate::config::HookPref;

/// How UDP traffic is counted per process.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum HookKind {
    /// raw_tp on sock_send_length / sock_recv_length (kernel >= 6.4)
    Tracepoint,
    /// fexit on udp{,v6}_{send,recv}msg (kernel >= 5.17 with BTF trampolines)
    Fexit,
}

impl HookKind {
    pub fn describe(self) -> &'static str {
        match self {
            HookKind::Tracepoint => "socket tracepoints",
            HookKind::Fexit => "UDP fexit probes",
        }
    }
}

fn btf_has(btf: &Btf, name: &str) -> bool {
    btf.type_by_name::<BtfType>(name).is_some()
}

/// Which counting hook can this kernel run? Decided from the kernel's own
/// BTF: a tracepoint exists if its `btf_trace_*` type does.
pub fn pick_hook(pref: HookPref) -> Result<HookKind> {
    let btf = Btf::from_vmlinux().context("kernel BTF (/sys/kernel/btf/vmlinux) is required")?;
    let tp =
        btf_has(&btf, "btf_trace_sock_send_length") && btf_has(&btf, "btf_trace_sock_recv_length");
    let fx = btf_has(&btf, "udp_sendmsg") && btf_has(&btf, "udp_recvmsg");
    match pref {
        HookPref::Tracepoint if tp => Ok(HookKind::Tracepoint),
        HookPref::Tracepoint => {
            bail!("kernel lacks sock_send_length/sock_recv_length tracepoints (need >= 6.4)")
        }
        HookPref::Fexit if fx => Ok(HookKind::Fexit),
        HookPref::Fexit => bail!("udp_sendmsg/udp_recvmsg not found in kernel BTF"),
        HookPref::Auto if tp => Ok(HookKind::Tracepoint),
        HookPref::Auto if fx => Ok(HookKind::Fexit),
        HookPref::Auto => {
            bail!("no usable hook: need kernel >= 6.4, or >= 5.17 with fexit support")
        }
    }
}

/// Can the fexit fallback also hook the IPv6 UDP functions? (IPv6 may be
/// built as a module, or not at all.)
pub fn has_udpv6_btf() -> bool {
    Btf::from_vmlinux()
        .map(|b| btf_has(&b, "udpv6_sendmsg") && btf_has(&b, "udpv6_recvmsg"))
        .unwrap_or(false)
}

/// Copy a map key or value into a bindgen'd struct.
///
/// Only for plain-old-data types made of integers (everything in intf.h),
/// where any byte pattern is a valid value. Short input leaves the rest at
/// its default.
fn from_bytes<T: Copy + Default>(b: &[u8]) -> T {
    let mut v = T::default();
    if b.len() >= size_of::<T>() {
        unsafe {
            std::ptr::copy_nonoverlapping(
                b.as_ptr(),
                (&mut v as *mut T).cast::<u8>(),
                size_of::<T>(),
            )
        };
    }
    v
}

/// Raise RLIMIT_MEMLOCK so maps can be created. Only matters on kernels
/// before 5.11, which charged BPF memory to it (newer ones use memcg).
pub fn bump_memlock() {
    let rl = libc::rlimit {
        rlim_cur: libc::RLIM_INFINITY,
        rlim_max: libc::RLIM_INFINITY,
    };
    if unsafe { libc::setrlimit(libc::RLIMIT_MEMLOCK, &rl) } != 0 {
        debug!(
            "could not raise RLIMIT_MEMLOCK: {}",
            std::io::Error::last_os_error()
        );
    }
}
